-- =============================================================================
-- Interactive Skeleton Builder — part 1 of 2: tables, protected prices,
-- server-side pricing, seed. GENERATED by scripts/gen-skeleton-migration.mjs
-- from src/lib/skeleton/catalog.js — edit the catalogue and regenerate.
--
-- Safe for the live shop: only NEW objects are created (plus one new nullable
-- column order_items.config_snapshot). No existing table, product, price,
-- order or function is changed. Running it twice changes nothing (the seed
-- uses "on conflict do nothing", so later admin edits are never overwritten).
-- Checkout keeps working exactly as before; part 2 (migration_skeleton_2_checkout.sql)
-- teaches place_order() about builder lines and is applied at launch.
-- Rollback notes at the bottom.
-- =============================================================================

-- 1. Tables ---------------------------------------------------------------------
create table if not exists public.skeleton_items (
  key text primary key,
  section text not null,
  grp text not null default '',
  name_en text not null,
  name_bn text not null default '',
  kind text not null check (kind in ('paired', 'single', 'grouped', 'pool')),
  half_price numeric not null check (half_price >= 0),
  full_price numeric check (full_price is null or full_price >= 0),
  weight_kg numeric not null default 0.15 check (weight_kg >= 0),
  meshes jsonb not null default '{}'::jsonb,
  aliases jsonb not null default '{}'::jsonb,
  pool_of text[],
  product_slug text,
  note_en text not null default '',
  note_bn text not null default '',
  is_active boolean not null default true,
  is_available boolean not null default true,
  listed boolean not null default true,
  sort int not null default 0,
  updated_at timestamptz not null default now()
);

create table if not exists public.skeleton_bundles (
  key text primary key check (key in ('half', 'full')),
  name_en text not null,
  name_bn text not null default '',
  price numeric not null check (price > 0),
  weight_kg numeric not null default 0 check (weight_kg >= 0),
  is_active boolean not null default true,
  product_slug text,
  sort int not null default 0,
  updated_at timestamptz not null default now()
);

create table if not exists public.skeleton_bundle_items (
  bundle text not null references public.skeleton_bundles(key) on delete cascade,
  item_key text not null references public.skeleton_items(key),
  mode text not null check (mode in ('half', 'full', 'single', 'pool')),
  qty int not null default 1 check (qty between 1 and 10),
  sort int not null default 0,
  primary key (bundle, item_key)
);

-- One saved builder configuration per signed-in customer (the guest cart lives
-- in the browser). Prices are never stored here; they are recomputed.
create table if not exists public.skeleton_carts (
  user_id uuid primary key references auth.users(id) on delete cascade,
  config jsonb not null,
  updated_at timestamptz not null default now()
);

-- Every price or set change made from the admin panel.
create table if not exists public.skeleton_change_log (
  id bigserial primary key,
  changed_at timestamptz not null default now(),
  actor text not null default '',
  what text not null,
  old_value jsonb,
  new_value jsonb,
  reason text not null default ''
);

-- Frozen copy of the builder configuration on the order line.
alter table public.order_items add column if not exists config_snapshot jsonb;

-- 2. Security ------------------------------------------------------------------
alter table public.skeleton_items enable row level security;
alter table public.skeleton_bundles enable row level security;
alter table public.skeleton_bundle_items enable row level security;
alter table public.skeleton_carts enable row level security;
alter table public.skeleton_change_log enable row level security;

drop policy if exists "Public read skeleton items" on public.skeleton_items;
create policy "Public read skeleton items" on public.skeleton_items for select using (true);
drop policy if exists "Admins update skeleton items" on public.skeleton_items;
create policy "Admins update skeleton items" on public.skeleton_items for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Public read skeleton bundles" on public.skeleton_bundles;
create policy "Public read skeleton bundles" on public.skeleton_bundles for select using (true);
drop policy if exists "Admins update skeleton bundles" on public.skeleton_bundles;
create policy "Admins update skeleton bundles" on public.skeleton_bundles for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

drop policy if exists "Public read skeleton bundle items" on public.skeleton_bundle_items;
create policy "Public read skeleton bundle items" on public.skeleton_bundle_items for select using (true);

drop policy if exists "Owner manages skeleton cart" on public.skeleton_carts;
create policy "Owner manages skeleton cart" on public.skeleton_carts for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

drop policy if exists "Admins read skeleton change log" on public.skeleton_change_log;
create policy "Admins read skeleton change log" on public.skeleton_change_log for select to authenticated using (public.is_admin());

revoke all on public.skeleton_items, public.skeleton_bundles, public.skeleton_bundle_items, public.skeleton_carts, public.skeleton_change_log from anon, authenticated;
grant select on public.skeleton_items, public.skeleton_bundles, public.skeleton_bundle_items to anon, authenticated;
grant update (name_en, name_bn, grp, note_en, note_bn, is_active, is_available, sort, meshes, aliases, updated_at) on public.skeleton_items to authenticated;
grant update (name_en, name_bn, is_active, sort, updated_at) on public.skeleton_bundles to authenticated;
grant select, insert, update, delete on public.skeleton_carts to authenticated;
grant select on public.skeleton_change_log to authenticated;

-- Approved prices and set contents are protected: a plain UPDATE cannot change
-- a price (the column is not even granted), and admins change them only through
-- admin_skeleton_set_price / admin_skeleton_set_bundle_item, which log the change.
create or replace function public.skeleton_guard_item_prices()
returns trigger language plpgsql as $$
begin
  if coalesce(current_setting('skeleton.price_change', true), '') <> 'allowed'
     and (new.half_price is distinct from old.half_price or new.full_price is distinct from old.full_price
          or new.kind is distinct from old.kind or new.weight_kg is distinct from old.weight_kg or new.pool_of is distinct from old.pool_of) then
    raise exception 'PRICE_PROTECTED' using errcode = '42501';
  end if;
  new.updated_at := now();
  return new;
end $$;
create or replace function public.skeleton_guard_bundle_prices()
returns trigger language plpgsql as $$
begin
  if coalesce(current_setting('skeleton.price_change', true), '') <> 'allowed'
     and (new.price is distinct from old.price or new.weight_kg is distinct from old.weight_kg) then
    raise exception 'PRICE_PROTECTED' using errcode = '42501';
  end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists skeleton_items_guard on public.skeleton_items;
create trigger skeleton_items_guard before update on public.skeleton_items for each row execute function public.skeleton_guard_item_prices();
drop trigger if exists skeleton_bundles_guard on public.skeleton_bundles;
create trigger skeleton_bundles_guard before update on public.skeleton_bundles for each row execute function public.skeleton_guard_bundle_prices();

create or replace function public.admin_skeleton_set_price(p_what text, p_key text, p_half numeric, p_full numeric, p_reason text)
returns void language plpgsql security definer set search_path = public as $$
declare v_old jsonb; v_new jsonb;
begin
  if not public.is_admin() then raise exception 'NOT_ADMIN' using errcode = '42501'; end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'REASON_REQUIRED'; end if;
  if p_half is null or p_half < 0 or (p_full is not null and p_full < 0) then raise exception 'INVALID_PRICE'; end if;
  perform set_config('skeleton.price_change', 'allowed', true);
  if p_what = 'item' then
    select jsonb_build_object('half', half_price, 'full', full_price) into v_old from public.skeleton_items where key = p_key;
    if v_old is null then raise exception 'UNKNOWN_ITEM'; end if;
    update public.skeleton_items set half_price = p_half, full_price = coalesce(p_full, full_price) where key = p_key;
    v_new := jsonb_build_object('half', p_half, 'full', coalesce(p_full, (v_old->>'full')::numeric));
  elsif p_what = 'bundle' then
    select jsonb_build_object('price', price) into v_old from public.skeleton_bundles where key = p_key;
    if v_old is null then raise exception 'UNKNOWN_BUNDLE'; end if;
    if p_half <= 0 then raise exception 'INVALID_PRICE'; end if;
    update public.skeleton_bundles set price = p_half where key = p_key;
    v_new := jsonb_build_object('price', p_half);
  else
    raise exception 'INVALID_TARGET';
  end if;
  perform set_config('skeleton.price_change', '', true);
  insert into public.skeleton_change_log (actor, what, old_value, new_value, reason)
  values (coalesce(auth.jwt() ->> 'email', ''), p_what || ':' || p_key || ':price', v_old, v_new, trim(p_reason));
end $$;
revoke all on function public.admin_skeleton_set_price(text, text, numeric, numeric, text) from public, anon;
grant execute on function public.admin_skeleton_set_price(text, text, numeric, numeric, text) to authenticated;

create or replace function public.admin_skeleton_set_bundle_item(p_bundle text, p_item text, p_include boolean, p_mode text, p_qty int, p_reason text)
returns void language plpgsql security definer set search_path = public as $$
declare v_old jsonb;
begin
  if not public.is_admin() then raise exception 'NOT_ADMIN' using errcode = '42501'; end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'REASON_REQUIRED'; end if;
  select to_jsonb(bi) into v_old from public.skeleton_bundle_items bi where bundle = p_bundle and item_key = p_item;
  if p_include then
    insert into public.skeleton_bundle_items (bundle, item_key, mode, qty, sort)
    values (p_bundle, p_item, p_mode, coalesce(p_qty, 1), coalesce((select max(sort) + 10 from public.skeleton_bundle_items where bundle = p_bundle), 0))
    on conflict (bundle, item_key) do update set mode = excluded.mode, qty = excluded.qty;
  else
    delete from public.skeleton_bundle_items where bundle = p_bundle and item_key = p_item;
  end if;
  insert into public.skeleton_change_log (actor, what, old_value, new_value, reason)
  values (coalesce(auth.jwt() ->> 'email', ''), 'bundle:' || p_bundle || ':' || p_item, v_old,
          case when p_include then jsonb_build_object('mode', p_mode, 'qty', coalesce(p_qty, 1)) else null end, trim(p_reason));
end $$;
revoke all on function public.admin_skeleton_set_bundle_item(text, text, boolean, text, int, text) from public, anon;
grant execute on function public.admin_skeleton_set_bundle_item(text, text, boolean, text, int, text) to authenticated;

-- 3. Pricing (the only price an order is charged; mirrors src/lib/skeleton/pricing.js)
-- Normal price of one item's pieces. A left + right is a pair at the pair price,
-- only when that is above one side (S2) and only for a real left + right (S3).
create or replace function public.skeleton_cost(p_kind text, p_half numeric, p_full numeric, l int, r int, s int)
returns numeric language sql immutable as $$
  select case
    when p_kind = 'paired' then
      case when coalesce(p_full, 0) > p_half
        then least(l, r) * p_full + (l + r - 2 * least(l, r)) * p_half
        else (l + r) * p_half end
    else s * p_half end
$$;

-- Saving of a set = its own pieces at normal prices − the fixed set price.
create or replace function public.skeleton_set_saving(p_bundle text)
returns numeric language sql stable security definer set search_path = public as $$
  select coalesce((
    select sum(case when i.kind = 'paired'
                    then public.skeleton_cost(i.kind, i.half_price, i.full_price, bi.qty, case when bi.mode = 'full' then bi.qty else 0 end, 0)
                    else bi.qty * i.half_price end)
      from public.skeleton_bundle_items bi join public.skeleton_items i on i.key = bi.item_key
     where bi.bundle = p_bundle), 0)
    - (select price from public.skeleton_bundles where key = p_bundle)
$$;

-- Does the selection contain every piece of the set? Grouped products are never
-- set pieces (S4) because only the set's own item keys are checked.
create or replace function public.skeleton_set_contains(p_bundle text, p_counts jsonb)
returns boolean language sql stable security definer set search_path = public as $$
  select not exists (
    select 1 from public.skeleton_bundle_items bi join public.skeleton_items i on i.key = bi.item_key
     where bi.bundle = p_bundle and (
       (i.kind = 'pool' and (select coalesce(sum(coalesce((p_counts -> k ->> 'S')::int, 0)), 0)
                               from unnest(array_prepend(i.key, coalesce(i.pool_of, '{}'::text[]))) k) < bi.qty)
       or (i.kind = 'paired' and bi.mode = 'full' and (coalesce((p_counts -> i.key ->> 'L')::int, 0) < bi.qty or coalesce((p_counts -> i.key ->> 'R')::int, 0) < bi.qty))
       or (i.kind = 'paired' and bi.mode <> 'full' and coalesce((p_counts -> i.key ->> 'L')::int, 0) + coalesce((p_counts -> i.key ->> 'R')::int, 0) < bi.qty)
       or (i.kind not in ('pool', 'paired') and coalesce((p_counts -> i.key ->> 'S')::int, 0) < bi.qty)
     ))
$$;

create or replace function public.skeleton_quote(p_config jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_pieces jsonb := p_config -> 'pieces';
  e jsonb; v_k text; v_s text; v_q int; v_qraw jsonb;
  it public.skeleton_items%rowtype;
  v_counts jsonb := '{}'::jsonb;
  v_rest jsonb; v_used jsonb := '{}'::jsonb;
  c jsonb; u jsonb;
  v_individual numeric := 0; v_saving numeric := 0;
  v_set public.skeleton_bundles%rowtype; v_has_set boolean := false;
  b public.skeleton_bundles%rowtype;
  bi record; pk record; x record;
  v_need int; v_take int; v_side text;
  v_lines jsonb := '[]'::jsonb;
  v_weight numeric := 0; v_n int := 0; v_extra numeric; v_first boolean;
begin
  if v_pieces is null or jsonb_typeof(v_pieces) <> 'array' then return jsonb_build_object('ok', false, 'error', 'invalid_config'); end if;
  if jsonb_array_length(v_pieces) > 200 then return jsonb_build_object('ok', false, 'error', 'too_many_pieces'); end if;

  for e in select value from jsonb_array_elements(v_pieces) loop
    if jsonb_typeof(e) <> 'object' then return jsonb_build_object('ok', false, 'error', 'invalid_config'); end if;
    v_k := e ->> 'k'; v_s := e ->> 's';
    select * into it from public.skeleton_items where key = v_k;
    if not found then return jsonb_build_object('ok', false, 'error', 'unknown_item', 'key', v_k); end if;
    if not it.is_active or not it.is_available then return jsonb_build_object('ok', false, 'error', 'unavailable_item', 'key', v_k); end if;
    if (it.kind = 'paired' and coalesce(v_s, '') not in ('L', 'R')) or (it.kind <> 'paired' and v_s is distinct from 'S') then
      return jsonb_build_object('ok', false, 'error', 'invalid_side', 'key', v_k);
    end if;
    v_qraw := e -> 'q';
    if v_qraw is null then v_q := 1;
    elsif jsonb_typeof(v_qraw) <> 'number' or (v_qraw::text)::numeric <> trunc((v_qraw::text)::numeric)
          or (v_qraw::text)::numeric < 1 or (v_qraw::text)::numeric > 10 then
      return jsonb_build_object('ok', false, 'error', 'invalid_qty', 'key', v_k);
    else v_q := (v_qraw::text)::numeric::int; end if;
    c := coalesce(v_counts -> v_k, '{"L":0,"R":0,"S":0}'::jsonb);
    if (c ->> v_s)::int > 0 then return jsonb_build_object('ok', false, 'error', 'duplicate_piece', 'key', v_k); end if;
    v_counts := jsonb_set(v_counts, array[v_k], jsonb_set(c, array[v_s], to_jsonb(v_q)));
    v_n := v_n + v_q;
  end loop;

  if v_n = 0 then
    return jsonb_build_object('ok', true, 'total', 0, 'individual', 0, 'saving', 0, 'set', null, 'lines', '[]'::jsonb, 'weight_kg', 0, 'pieces', 0);
  end if;

  select coalesce(sum(public.skeleton_cost(i.kind, i.half_price, i.full_price, (cnt.value ->> 'L')::int, (cnt.value ->> 'R')::int, (cnt.value ->> 'S')::int)), 0)
    into v_individual from jsonb_each(v_counts) cnt join public.skeleton_items i on i.key = cnt.key;

  -- S1: the bigger set is checked first; S6: a saving <= 0 is never applied.
  for b in select * from public.skeleton_bundles where is_active order by case key when 'full' then 0 else 1 end loop
    if public.skeleton_set_saving(b.key) > 0 and public.skeleton_set_contains(b.key, v_counts) then
      v_set := b; v_has_set := true; exit;
    end if;
  end loop;

  v_rest := v_counts;
  if v_has_set then
    v_saving := public.skeleton_set_saving(v_set.key);
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('type', 'set', 'key', v_set.key, 'name_en', v_set.name_en, 'name_bn', v_set.name_bn, 'amount', v_set.price));
    v_weight := v_weight + v_set.weight_kg;
    for bi in select sbi.*, i.kind, i.pool_of from public.skeleton_bundle_items sbi join public.skeleton_items i on i.key = sbi.item_key
               where sbi.bundle = v_set.key order by sbi.sort, sbi.item_key loop
      if bi.kind = 'pool' then
        v_need := bi.qty;
        for pk in select k, n from unnest(array_prepend(bi.item_key, coalesce(bi.pool_of, '{}'::text[]))) with ordinality as t(k, n) order by n loop
          exit when v_need <= 0;
          c := v_rest -> pk.k;
          continue when c is null;
          v_take := least(v_need, (c ->> 'S')::int);
          if v_take > 0 then
            v_rest := jsonb_set(v_rest, array[pk.k, 'S'], to_jsonb((c ->> 'S')::int - v_take));
            u := coalesce(v_used -> pk.k, '{"L":0,"R":0,"S":0}'::jsonb);
            v_used := jsonb_set(v_used, array[pk.k], jsonb_set(u, array['S'], to_jsonb((u ->> 'S')::int + v_take)));
            v_need := v_need - v_take;
          end if;
        end loop;
      else
        c := v_rest -> bi.item_key;
        u := coalesce(v_used -> bi.item_key, '{"L":0,"R":0,"S":0}'::jsonb);
        if bi.kind = 'paired' and bi.mode = 'full' then
          v_rest := jsonb_set(jsonb_set(v_rest, array[bi.item_key, 'L'], to_jsonb((c ->> 'L')::int - bi.qty)), array[bi.item_key, 'R'], to_jsonb((c ->> 'R')::int - bi.qty));
          u := jsonb_set(jsonb_set(u, array['L'], to_jsonb((u ->> 'L')::int + bi.qty)), array['R'], to_jsonb((u ->> 'R')::int + bi.qty));
        else
          v_side := case when bi.kind = 'paired' then case when (c ->> 'L')::int >= bi.qty then 'L' else 'R' end else 'S' end;
          v_rest := jsonb_set(v_rest, array[bi.item_key, v_side], to_jsonb((c ->> v_side)::int - bi.qty));
          u := jsonb_set(u, array[v_side], to_jsonb((u ->> v_side)::int + bi.qty));
        end if;
        v_used := jsonb_set(v_used, array[bi.item_key], u);
      end if;
    end loop;
    for x in select u2.key, u2.value, i.name_en, i.name_bn from jsonb_each(v_used) u2 join public.skeleton_items i on i.key = u2.key loop
      for v_side in select unnest(array['L', 'R', 'S']) loop
        if (x.value ->> v_side)::int > 0 then
          v_lines := v_lines || jsonb_build_array(jsonb_build_object('type', 'included', 'key', x.key, 'side', v_side, 'qty', (x.value ->> v_side)::int,
                                                                      'name_en', x.name_en, 'name_bn', x.name_bn, 'amount', 0));
        end if;
      end loop;
    end loop;
  end if;

  for x in select r.key, r.value, i.* from jsonb_each(v_rest) r join public.skeleton_items i on i.key = r.key loop
    c := v_counts -> x.key;
    u := coalesce(v_used -> x.key, '{"L":0,"R":0,"S":0}'::jsonb);
    v_extra := public.skeleton_cost(x.kind, x.half_price, x.full_price, (c ->> 'L')::int, (c ->> 'R')::int, (c ->> 'S')::int)
             - public.skeleton_cost(x.kind, x.half_price, x.full_price, (u ->> 'L')::int, (u ->> 'R')::int, (u ->> 'S')::int);
    v_first := true;
    for v_side in select unnest(array['L', 'R', 'S']) loop
      if (x.value ->> v_side)::int > 0 then
        v_lines := v_lines || jsonb_build_array(jsonb_build_object('type', 'extra', 'key', x.key, 'side', v_side, 'qty', (x.value ->> v_side)::int,
                                                                    'name_en', x.name_en, 'name_bn', x.name_bn, 'amount', case when v_first then v_extra else 0 end));
        v_weight := v_weight + (x.value ->> v_side)::int * x.weight_kg;
        v_first := false;
      end if;
    end loop;
  end loop;

  return jsonb_build_object('ok', true, 'total', v_individual - v_saving, 'individual', v_individual, 'saving', v_saving,
    'set', case when v_has_set then v_set.key end, 'lines', v_lines, 'weight_kg', round(v_weight, 3), 'pieces', v_n);
end $$;

-- The full public catalogue for the builder page (one call).
create or replace function public.skeleton_catalog()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(to_jsonb(i) order by i.sort) from public.skeleton_items i), '[]'::jsonb),
    'bundles', coalesce((select jsonb_agg(to_jsonb(b) || jsonb_build_object('items', coalesce((
        select jsonb_agg(jsonb_build_object('item_key', bi.item_key, 'mode', bi.mode, 'qty', bi.qty) order by bi.sort, bi.item_key)
          from public.skeleton_bundle_items bi where bi.bundle = b.key), '[]'::jsonb)) order by b.sort) from public.skeleton_bundles b), '[]'::jsonb)
  )
$$;

revoke all on function public.skeleton_cost(text, numeric, numeric, int, int, int), public.skeleton_set_saving(text),
  public.skeleton_set_contains(text, jsonb), public.skeleton_quote(jsonb), public.skeleton_catalog() from public;
grant execute on function public.skeleton_quote(jsonb), public.skeleton_catalog() to anon, authenticated;

-- 4. Seed: the approved catalogue (never overwrites later admin edits) -------------
insert into public.skeleton_items (key, section, grp, name_en, name_bn, kind, half_price, full_price, weight_kg, meshes, aliases, pool_of, product_slug, note_en, note_bn, is_active, is_available, listed, sort) values
  ('base_vault', 'head', 'Base', 'Base of the skull with vault', 'বেস অব দ্য স্কাল (ভল্টসহ)', 'grouped', 4100, null, 0.763, '{"S":["frontal","parietal_L","parietal_R","occipital","temporal_L","temporal_R","sphenoid","ethmoid"]}'::jsonb, '{}'::jsonb, null, 'base-of-the-skull-with-vault', 'One assembled model of the skull base and vault.', 'খুলির বেস ও ভল্টের একটি সম্পূর্ণ মডেল।', true, true, true, 10),
